actions.script:
import groovy.json.JsonSlurper
import org.moqui.impl.context.ArtifactExecutionFacadeImpl
import org.moqui.impl.service.ServiceDefinition

String verbAuthz = ServiceDefinition.getVerbFromName(serviceName ?: '')
String authzActionEnumId = ServiceDefinition.getVerbAuthzActionEnum(verbAuthz)?.name()
boolean authorized = authzActionEnumId ? ArtifactExecutionFacadeImpl.isPermitted("AT_SERVICE:${authzActionEnumId}:${serviceName}", ec) : false
if (!authorized) {
    ec.message.addError("Access denied for service ${serviceName}")
    return
}

def sd = ec.serviceFacade.getServiceDefinition(serviceName)
Closure<Boolean> isMutatingService = { String sn ->
    String lowered = (sn ?: '').toLowerCase()
    return ['create#', 'update#', 'store#', 'delete#', 'remove#', 'assign#', 'cancel#', 'close#', 'approve#',
            'complete#', 'submit#', 'set#', 'move#', 'change#'].any { lowered.contains(it) }
}
Closure<Map> nodeToMap = { Object nodeObj, String direction ->
    def node = nodeObj
    return [
            name: node?.attribute('name'),
            direction: direction,
            type: node?.attribute('type'),
            required: 'true'.equalsIgnoreCase((node?.attribute('required') ?: '').toString()),
            entityName: node?.attribute('entity-name'),
            defaultValue: node?.attribute('default-value')
    ]
}
Closure<Boolean> isIdentityOperand = { Map operand ->
    String operandName = (operand?.name ?: '') as String
    String operandType = (operand?.type ?: '') as String
    String loweredName = operandName.toLowerCase()
    String loweredType = operandType.toLowerCase()
    return loweredName.endsWith('id') || loweredName.endsWith('seqid') || loweredType == 'id'
}
Closure<Map> deriveEntityAutoSignature = { String currentServiceName ->
    String actionVerb = ServiceDefinition.getVerbFromName(currentServiceName ?: '') ?: ''
    String actionNoun = ServiceDefinition.getNounFromName(currentServiceName ?: '') ?: ''
    if (!(actionVerb in ['create', 'update', 'store', 'delete']) || !actionNoun || !ec.entity.isEntityDefined(actionNoun)) return null

    def ed = ec.entity.getEntityDefinition(actionNoun)
    List<String> pkFieldNames = (ed?.getPkFieldNames() ?: []) as List<String>
    List<String> allFieldNames = (ed?.getAllFieldNames() ?: []) as List<String>
    List<Map> derivedInParameterList = []
    allFieldNames.each { String fieldName ->
        def fieldNode = ed.getFieldNode(fieldName)
        boolean required = false
        if (actionVerb == 'create') {
            required = 'true'.equalsIgnoreCase((fieldNode?.attribute('not-null') ?: '').toString()) && !pkFieldNames.contains(fieldName)
            if (!required && pkFieldNames.size() > 1 && pkFieldNames.contains(fieldName) &&
                    fieldName.endsWith('Id') && !fieldName.endsWith('SeqId')) {
                required = true
            }
        } else if (actionVerb in ['update', 'delete']) {
            required = pkFieldNames.contains(fieldName)
        }
        String fieldType = (fieldNode?.attribute('type') ?: '') as String
        boolean identity = fieldName.toLowerCase().endsWith('id') || fieldName.toLowerCase().endsWith('seqid') || fieldType.toLowerCase() == 'id'
        String role
        if (fieldName.toLowerCase().endsWith('enumid') || fieldName.toLowerCase().endsWith('typeenumid') || fieldName.toLowerCase() == 'statusid') {
            role = 'enum_operand'
        } else if (fieldName.toLowerCase().endsWith('seqid')) {
            role = 'generated_operand'
        } else if (identity) {
            role = required ? 'parent_operand' : 'lookup_operand'
        } else {
            role = 'literal_value_operand'
        }
        derivedInParameterList << [
                name        : fieldName,
                direction   : 'in',
                type        : fieldType,
                required    : required,
                entityName  : actionNoun,
                fieldName   : fieldName,
                defaultValue: fieldNode?.attribute('default'),
                source      : 'entity-auto-derived',
                identity    : identity,
                role        : role
        ]
    }
    List<Map> derivedOutParameterList = pkFieldNames.collect { String fieldName ->
        def fieldNode = ed.getFieldNode(fieldName)
        String fieldType = (fieldNode?.attribute('type') ?: '') as String
        boolean identity = fieldName.toLowerCase().endsWith('id') || fieldName.toLowerCase().endsWith('seqid') || fieldType.toLowerCase() == 'id'
        return [
                name        : fieldName,
                direction   : 'out',
                type        : fieldType,
                required    : false,
                entityName  : actionNoun,
                fieldName   : fieldName,
                defaultValue: null,
                source      : 'entity-auto-derived',
                identity    : identity,
                role        : identity ? 'produced_identity_operand' : 'produced_operand'
        ]
    }
    boolean mutatesState = isMutatingService(currentServiceName)
    List<String> requiredOperandList = derivedInParameterList.findAll { it.required }.collect { it.name }
    List<String> optionalOperandList = derivedInParameterList.findAll { !it.required }.collect { it.name }
    List<String> producedOperandList = derivedOutParameterList.collect { it.name }.findAll { it }
    List<String> requiredIdOperandList = derivedInParameterList.findAll { it.required && it.identity }.collect { it.name }
    List<String> producedIdOperandList = derivedOutParameterList.findAll { it.identity }.collect { it.name }
    return [
            serviceName            : currentServiceName,
            description            : "Implicit entity-auto signature for ${currentServiceName}",
            verb                   : actionVerb,
            noun                   : actionNoun,
            mutatesState           : mutatesState,
            morphismRole           : 'entity_auto_service',
            authorized             : true,
            authzActionEnumId      : authzActionEnumId,
            inParameterList        : derivedInParameterList,
            outParameterList       : derivedOutParameterList,
            requiredOperandList    : requiredOperandList,
            optionalOperandList    : optionalOperandList,
            producedOperandList    : producedOperandList,
            requiredIdOperandList  : requiredIdOperandList,
            producedIdOperandList  : producedIdOperandList
    ]
}
Closure<Map> normalizeOperand = { Map operand, String direction ->
    Map normalized = [:]
    if (operand) normalized.putAll(operand)
    normalized.direction = direction
    if (direction == 'out') normalized.required = false
    normalized.identity = normalized.containsKey('identity') ? Boolean.valueOf(normalized.identity?.toString()) : isIdentityOperand(normalized)
    if (!normalized.containsKey('fieldName')) normalized.fieldName = normalized.name
    if (!normalized.containsKey('source')) normalized.source = 'morphism-parameter'
    if (!normalized.role) {
        String loweredName = ((normalized.name ?: '') as String).toLowerCase()
        if (direction == 'out') {
            normalized.role = normalized.identity ? 'produced_identity_operand' : 'produced_operand'
        } else if (loweredName.endsWith('enumid') || loweredName.endsWith('typeenumid') || loweredName == 'statusid') {
            normalized.role = 'enum_operand'
        } else if (loweredName.endsWith('seqid')) {
            normalized.role = 'generated_operand'
        } else if (normalized.identity) {
            normalized.role = normalized.required ? 'parent_operand' : 'lookup_operand'
        } else {
            normalized.role = 'literal_value_operand'
        }
    }
    return normalized
}
Closure<List<String>> parseStringList = { Object rawValue ->
    if (rawValue == null) return []
    String text = rawValue.toString().trim()
    if (!text || text == 'null') return []
    try {
        def parsed = new JsonSlurper().parseText(text)
        if (parsed instanceof Collection) return parsed.collect { it?.toString() }.findAll { it }
    } catch (Exception ignored) {}
    return []
}

def morphismRecord = ec.entity.find('moqui.math.ct.Morphism')
        .condition('categoryId', 'AgentXmlActionsDsl')
        .condition('serviceName', serviceName)
        .one()
Map derivedEntityAutoSignature = deriveEntityAutoSignature(serviceName)
if (morphismRecord) {
    def parameterRows = ec.entity.find('moqui.math.Parameter')
            .condition('morphismId', morphismRecord.morphismId)
            .orderBy('sequenceNum')
            .list() ?: []

    List<Map> persistedInParameters = []
    List<Map> persistedOutParameters = []
    List<String> persistedRequiredOperands = []
    List<String> persistedOptionalOperands = []
    List<String> persistedProducedOperands = []
    List<String> persistedRequiredIdOperands = []
    List<String> persistedProducedIdOperands = []

    parameterRows.each { def row ->
        String parameterDefId = (row.parameterDefId ?: '') as String
        String textValue = row.textValue as String
        if (parameterDefId == 'AgSrvInOperandDef' && textValue) {
            try {
                def parsed = new JsonSlurper().parseText(textValue)
                if (parsed instanceof Map) persistedInParameters.add(normalizeOperand(parsed as Map, 'in'))
            } catch (Exception ignored) {}
        } else if (parameterDefId == 'AgSrvOutOperandDef' && textValue) {
            try {
                def parsed = new JsonSlurper().parseText(textValue)
                if (parsed instanceof Map) persistedOutParameters.add(normalizeOperand(parsed as Map, 'out'))
            } catch (Exception ignored) {}
        } else if (parameterDefId == 'AgSrvRequiredOperandListDef') {
            persistedRequiredOperands = parseStringList(textValue)
        } else if (parameterDefId == 'AgSrvOptionalOperandListDef') {
            persistedOptionalOperands = parseStringList(textValue)
        } else if (parameterDefId == 'AgSrvProducedOperandListDef') {
            persistedProducedOperands = parseStringList(textValue)
        } else if (parameterDefId == 'AgSrvRequiredIdOperandListDef') {
            persistedRequiredIdOperands = parseStringList(textValue)
        } else if (parameterDefId == 'AgSrvProducedIdOperandListDef') {
            persistedProducedIdOperands = parseStringList(textValue)
        }
    }

    boolean useDerivedEntityAuto = false
    if (derivedEntityAutoSignature && (persistedInParameters || persistedOutParameters)) {
        List<Map> allPersistedOperands = []
        allPersistedOperands.addAll(persistedInParameters)
        allPersistedOperands.addAll(persistedOutParameters)
        boolean allEntityAuto = allPersistedOperands && allPersistedOperands.every { Map operand ->
            ((operand.source ?: '') as String) in ['entity-auto-service', 'entity-auto-derived']
        }
        boolean persistedTooThin = persistedInParameters.every { Map operand -> Boolean.TRUE.equals(operand.identity) } &&
                derivedEntityAutoSignature.inParameterList.size() > persistedInParameters.size()
        useDerivedEntityAuto = allEntityAuto && persistedTooThin
    }
    if (useDerivedEntityAuto) {
        morphism = derivedEntityAutoSignature
        return
    }

    int serviceDefinitionInCount = sd ? ((sd.getInParameterNames() ?: []) as List).size() : 0
    int serviceDefinitionOutCount = sd ? ((sd.getOutParameterNames() ?: []) as List).size() : 0
    boolean persistedSignatureTooThinForServiceDef = false
    if (sd && (persistedInParameters || persistedOutParameters)) {
        int persistedTotal = persistedInParameters.size() + persistedOutParameters.size()
        int serviceDefinitionTotal = serviceDefinitionInCount + serviceDefinitionOutCount
        boolean persistedMissingRichBusinessOperands = !persistedInParameters.any { Map operand ->
            String operandName = ((operand?.name ?: '') as String)
            operandName in ['customerPartyId', 'vendorPartyId', 'organizationPartyId', 'fromPartyId', 'toPartyId',
                    'timePeriodId', 'glAccountId', 'productId', 'requiredByDate', 'responseRequiredDate']
        }
        persistedSignatureTooThinForServiceDef =
                serviceDefinitionTotal >= (persistedTotal + 4) &&
                (persistedMissingRichBusinessOperands || serviceDefinitionInCount > persistedInParameters.size())
    }
    if (persistedSignatureTooThinForServiceDef) {
        persistedInParameters = []
        persistedOutParameters = []
        persistedRequiredOperands = []
        persistedOptionalOperands = []
        persistedProducedOperands = []
        persistedRequiredIdOperands = []
        persistedProducedIdOperands = []
    }

    if (persistedInParameters || persistedOutParameters) {
        String actionVerb = ServiceDefinition.getVerbFromName(serviceName ?: '') ?: ''
        String actionNoun = ServiceDefinition.getNounFromName(serviceName ?: '') ?: ''
        boolean mutatesState = isMutatingService(serviceName)
        if (!persistedRequiredOperands) persistedRequiredOperands = persistedInParameters.findAll { it.required }.collect { it.name }
        if (!persistedOptionalOperands) persistedOptionalOperands = persistedInParameters.findAll { !it.required }.collect { it.name }
        if (!persistedProducedOperands) persistedProducedOperands = persistedOutParameters.collect { it.name }.findAll { it }
        if (!persistedRequiredIdOperands) persistedRequiredIdOperands = persistedInParameters.findAll { it.required && it.identity }.collect { it.name }
        if (!persistedProducedIdOperands) persistedProducedIdOperands = persistedOutParameters.findAll { it.identity }.collect { it.name }
        morphism = [
                serviceName            : serviceName,
                description            : morphismRecord.description ?: '',
                verb                   : actionVerb,
                noun                   : actionNoun,
                mutatesState           : mutatesState,
                morphismRole           : mutatesState ? 'composite_morphism' : 'read_projection',
                authorized             : true,
                authzActionEnumId      : authzActionEnumId,
                inParameterList        : persistedInParameters,
                outParameterList       : persistedOutParameters,
                requiredOperandList    : persistedRequiredOperands,
                optionalOperandList    : persistedOptionalOperands,
                producedOperandList    : persistedProducedOperands,
                requiredIdOperandList  : persistedRequiredIdOperands,
                producedIdOperandList  : persistedProducedIdOperands
        ]
        return
    }
}

if (!sd) {
    if (!derivedEntityAutoSignature) {
        ec.message.addError("Service not found: ${serviceName}")
        return
    }
    morphism = derivedEntityAutoSignature
    return
}

List<Map> inParameterList = []
(sd.getInParameterNames() ?: []).each { String parameterName ->
    def paramNode = sd.getInParameter(parameterName)
    if (paramNode) inParameterList << nodeToMap(paramNode, 'in')
}

List<Map> outParameterList = []
(sd.getOutParameterNames() ?: []).each { String parameterName ->
    def paramNode = sd.getOutParameter(parameterName)
    if (paramNode) outParameterList << nodeToMap(paramNode, 'out')
}

String actionVerb = ServiceDefinition.getVerbFromName(serviceName ?: '') ?: ''
String actionNoun = ServiceDefinition.getNounFromName(serviceName ?: '') ?: ''
boolean mutatesState = isMutatingService(serviceName)
List<String> requiredIdOperands = inParameterList.findAll {
    it.required && ((((it.name ?: '') as String).toLowerCase().endsWith('id')) ||
            ((((it.name ?: '') as String).toLowerCase().endsWith('seqid'))) ||
            (((it.type ?: '') as String).toLowerCase() == 'id'))
}.collect { it.name }
List<String> producedIdOperands = outParameterList.findAll {
    ((((it.name ?: '') as String).toLowerCase().endsWith('id')) ||
            ((((it.name ?: '') as String).toLowerCase().endsWith('seqid'))) ||
            (((it.type ?: '') as String).toLowerCase() == 'id'))
}.collect { it.name }

morphism = [
        serviceName: serviceName,
        description: sd.serviceNode?.attribute('description') ?: '',
        verb: actionVerb,
        noun: actionNoun,
        mutatesState: mutatesState,
        morphismRole: mutatesState ? 'composite_morphism' : 'read_projection',
        authorized: true,
        authzActionEnumId: authzActionEnumId,
        inParameterList: inParameterList,
        outParameterList: outParameterList,
        requiredOperandList: inParameterList.findAll { it.required }.collect { it.name },
        optionalOperandList: inParameterList.findAll { !it.required }.collect { it.name },
        requiredIdOperandList: requiredIdOperands,
        producedIdOperandList: producedIdOperands
]

import groovy.json.JsonSlurper import org.moqui.impl.service.ServiceDefinition
Map signatureResult = ec.service.sync() .name('org.moqui.agent.AgentAlgebraicServices.get#MorphismSignature') .parameters([serviceName: serviceName]) .call() if (ec.message.hasError() || !(signatureResult?.morphism instanceof Map)) { return } String authzActionEnumId = (signatureResult.morphism.authzActionEnumId ?: '') as String
int effectiveMaxDepth = Math.max(1, (maxDepth ?: 12) as Integer) JsonSlurper jsonSlurper = new JsonSlurper()
Closure<List<String>> parseListValue = { Object rawValue -> if (rawValue == null) return [] String text = rawValue.toString().trim() if (!text || text == 'null') return [] if (text.startsWith('[') && text.endsWith(']')) { try { def parsed = jsonSlurper.parseText(text) if (parsed instanceof Collection) return parsed.collect { it?.toString() }.findAll { it } } catch (Exception ignored) {} } return [text] } Closure<String> firstParamValue = { List parameterList, String parameterDefId -> def parameter = parameterList.find { it.parameterDefId == parameterDefId } return parameter ? ((parameter.textValue ?: parameter.symbolicValue) as String) : null } Closure<List<String>> listParamValues = { List parameterList, String parameterDefId -> List<String> values = [] parameterList.findAll { it.parameterDefId == parameterDefId }.each { param -> values.addAll(parseListValue(param.textValue ?: param.symbolicValue)) } return values.findAll { it && it != 'null' }.unique().sort() } Closure<Map> loadServiceMorphism = { String currentServiceName -> if (!currentServiceName || currentServiceName.startsWith('component://')) return null def morphism = ec.entity.find('moqui.math.ct.Morphism') .condition('categoryId', 'AgentXmlActionsDsl') .condition('serviceName', currentServiceName) .useCache(true) .one() if (!morphism) { String currentVerb = ServiceDefinition.getVerbFromName(currentServiceName ?: '') ?: '' String currentNoun = ServiceDefinition.getNounFromName(currentServiceName ?: '') ?: '' boolean serviceDefined = ec.serviceFacade.isServiceDefined(currentServiceName) boolean entityDefined = currentNoun ? ec.entity.isEntityDefined(currentNoun) : false if (!serviceDefined && !entityDefined) return null List<String> fallbackRead = [] List<String> fallbackWrite = [] List<String> fallbackEffects = [] String loweredVerb = currentVerb.toLowerCase() if (entityDefined) { if (['create', 'update', 'store', 'delete', 'remove'].contains(loweredVerb)) { fallbackWrite.add(currentNoun) } else if (['find', 'get', 'list'].contains(loweredVerb)) { fallbackRead.add(currentNoun) } } if ('create'.equals(loweredVerb)) fallbackEffects.add('create_record') else if (['update', 'store'].contains(loweredVerb)) fallbackEffects.add('update_record') else if (['delete', 'remove'].contains(loweredVerb)) fallbackEffects.add('delete_record') else if (['find', 'get'].contains(loweredVerb)) fallbackEffects.add('read_one') else if ('list'.equals(loweredVerb)) fallbackEffects.add('read_list') return [ morphism: null, parameters: [], fallbackRead: fallbackRead.unique().sort(), fallbackWrite: fallbackWrite.unique().sort(), fallbackCalled: [], fallbackEffects: fallbackEffects.unique(), fallbackStatementClass: entityDefined ? 'entity_auto_service' : 'service_definition_only', fallbackOpaque: !entityDefined ] } List parameterList = ec.entity.find('moqui.math.Parameter') .condition('morphismId', morphism.morphismId) .orderBy('sequenceNum') .useCache(true) .list() ?: [] return [morphism: morphism, parameters: parameterList] }
Set<String> visitedServices = new LinkedHashSet<>() Set<String> directReadEntities = new LinkedHashSet<>() Set<String> directWrittenEntities = new LinkedHashSet<>() Set<String> directCalledServices = new LinkedHashSet<>() Set<String> effectiveReadEntities = new LinkedHashSet<>() Set<String> effectiveWrittenEntities = new LinkedHashSet<>() Set<String> effectiveCalledServices = new LinkedHashSet<>() Set<String> operationEffects = new LinkedHashSet<>() Set<String> statementClasses = new LinkedHashSet<>() Set<String> opaqueServices = new LinkedHashSet<>() Set<String> opaquePaths = new LinkedHashSet<>() Set<String> recursiveServices = new LinkedHashSet<>() boolean cycleDetected = false Map<String, List<String>> adjacency = [:]
Closure<Void> walkService walkService = { String currentServiceName, int depth, List<String> stack -> if (!currentServiceName) return if (depth > effectiveMaxDepth) { opaquePaths.add((stack + [currentServiceName]).join(' -> ') + ' [maxDepth]') return } if (stack.contains(currentServiceName)) { cycleDetected = true opaquePaths.add((stack + [currentServiceName]).join(' -> ') + ' [cycle]') return }
Map loaded = loadServiceMorphism(currentServiceName) if (!loaded) { opaquePaths.add((stack + [currentServiceName]).join(' -> ') + ' [missing]') return }
List parameterList = loaded.parameters as List List<String> currentRead = (loaded.fallbackRead ?: listParamValues(parameterList, 'AgSrvReadEntitiesDef')) as List<String> List<String> currentWrite = (loaded.fallbackWrite ?: listParamValues(parameterList, 'AgSrvWrittenEntitiesDef')) as List<String> List<String> currentCalled = (loaded.fallbackCalled ?: listParamValues(parameterList, 'AgSrvStepCalledServiceDef')) as List<String> List<String> currentEffects = (loaded.fallbackEffects ?: listParamValues(parameterList, 'AgMorphOperationEffectDef')) as List<String> String currentStatementClass = (loaded.fallbackStatementClass ?: firstParamValue(parameterList, 'AgMorphStatementClassDef')) as String boolean currentOpaque = Boolean.TRUE.equals(loaded.fallbackOpaque) || 'Y'.equalsIgnoreCase(firstParamValue(parameterList, 'AgMorphOpaqueDef')) currentCalled = currentCalled.findAll { String calledServiceName -> calledServiceName && calledServiceName != 'null' }.unique().sort()
if (depth == 0) { directReadEntities.addAll(currentRead) directWrittenEntities.addAll(currentWrite) directCalledServices.addAll(currentCalled) }
visitedServices.add(currentServiceName) effectiveReadEntities.addAll(currentRead) effectiveWrittenEntities.addAll(currentWrite) effectiveCalledServices.addAll(currentCalled) operationEffects.addAll(currentEffects) if (currentStatementClass) statementClasses.add(currentStatementClass) if (currentOpaque) { opaqueServices.add(currentServiceName) opaquePaths.add((stack + [currentServiceName]).join(' -> ') + ' [opaque]') } adjacency[currentServiceName] = currentCalled
List<String> nextStack = stack + [currentServiceName] currentCalled.each { String calledServiceName -> if (calledServiceName == currentServiceName) { recursiveServices.add(currentServiceName) opaquePaths.add((nextStack + [calledServiceName]).join(' -> ') + ' [recursive_self_call]') return } walkService(calledServiceName, depth + 1, nextStack) } }
walkService(serviceName, 0, [])
effectSummary = [ serviceName: serviceName, authorized: true, authzActionEnumId: authzActionEnumId, maxDepth: effectiveMaxDepth, visitedServices: visitedServices as List, directReadEntities: directReadEntities as List, directWrittenEntities: directWrittenEntities as List, directCalledServices: directCalledServices as List, effectiveReadEntities: effectiveReadEntities as List, effectiveWrittenEntities: effectiveWrittenEntities as List, effectiveCalledServices: effectiveCalledServices as List, operationEffects: operationEffects as List, statementClasses: statementClasses as List, opaqueServices: opaqueServices as List, recursiveServices: recursiveServices as List, opaquePaths: opaquePaths as List, cycleDetected: cycleDetected, adjacency: adjacency ]

Closure<String> packageFromEntityName = { String fullEntityName -> int lastDotIdx = fullEntityName ? fullEntityName.lastIndexOf('.') : -1 return lastDotIdx > 0 ? fullEntityName.substring(0, lastDotIdx) : '' } Closure<String> prettyFromEntityName = { String fullEntityName -> String localName = fullEntityName?.tokenize('.')?.last() ?: '' return localName .replaceAll(/([a-z0-9])([A-Z])/, '$1 $2') .replaceAll(/([A-Z]+)([A-Z][a-z])/, '$1 $2') } Closure<Set<String>> tokenize = { String text -> return text ? text.toLowerCase().split(/[^a-z0-9]+/).findAll { it && it.length() > 2 } as Set<String> : ([] as Set<String>) }
int effectiveLimit = Math.max(1, (limit ?: 20) as Integer) int fetchLimit = Math.max(effectiveLimit * 10, 300) Set<String> queryTerms = tokenize(queryText) objectList = []
def rows = ec.entity.find('moqui.math.ct.CategoryObject') .condition('categoryId', 'AgentEntityModel') .orderBy('objectEntityName') .limit(fetchLimit) .list() ?: []
rows.each { row -> String entityName = (row.objectEntityName ?: '') as String if (!entityName || !ec.entity.isEntityDefined(entityName)) return def ed = ec.entity.getEntityDefinition(entityName) if (!ed) return String currentType = ed.isViewEntity ? 'view-entity' : 'entity' if (entityType && entityType != currentType) return String prettyName = prettyFromEntityName(entityName) String haystack = "${entityName} ${(row.objectName ?: '')} ${prettyName} ${(row.description ?: '')}".toLowerCase() if (queryTerms && !queryTerms.any { haystack.contains(it) }) return objectList << [ categoryObjectId: row.categoryObjectId, objectName: entityName, objectType: currentType, packageName: packageFromEntityName(entityName), prettyName: prettyName, primaryKeyFieldNames: ed.getPkFieldNames() ] if (objectList.size() >= effectiveLimit) return }
objectList = objectList.take(effectiveLimit) objectCount = objectList.size()

import org.moqui.impl.entity.EntityJavaUtil.RelationshipInfo
Closure<String> packageFromEntityName = { String fullEntityName -> int lastDotIdx = fullEntityName ? fullEntityName.lastIndexOf('.') : -1 return lastDotIdx > 0 ? fullEntityName.substring(0, lastDotIdx) : '' } Closure<String> prettyFromEntityName = { String fullEntityName -> String localName = fullEntityName?.tokenize('.')?.last() ?: '' return localName .replaceAll(/([a-z0-9])([A-Z])/, '$1 $2') .replaceAll(/([A-Z]+)([A-Z][a-z])/, '$1 $2') }
if (!ec.entity.isEntityDefined(entityName)) { ec.message.addError("Entity not defined: ${entityName}") return }
def ed = ec.entity.getEntityDefinition(entityName) List<String> pkFieldNames = (ed.getPkFieldNames() ?: []) as List<String> List<Map> fieldList = [] (ed.getAllFieldNames() ?: []).each { String fieldName -> def fieldNode = ed.getFieldNode(fieldName) fieldList << [ fieldName: fieldName, type: fieldNode?.attribute('type'), isPk: pkFieldNames.contains(fieldName), required: 'true'.equalsIgnoreCase((fieldNode?.attribute('is-required') ?: fieldNode?.attribute('required') ?: '').toString()) ] }
List<Map> relationshipList = [] (ed.getRelationshipsInfo(false) ?: []).each { RelationshipInfo relInfo -> relationshipList << [ relationshipName: relInfo.relationshipName, relatedEntityName: relInfo.relatedEntityName, type: relInfo.type, shortAlias: relInfo.shortAlias, dependent: relInfo.dependent ] }
objectSchema = [ entityName: entityName, objectType: ed.isViewEntity ? 'view-entity' : 'entity', packageName: packageFromEntityName(entityName), prettyName: prettyFromEntityName(entityName), primaryKeyFieldNames: pkFieldNames, allFieldNames: ed.getAllFieldNames(), fieldList: fieldList, relationshipList: relationshipList ]

import java.util.regex.Matcher import java.util.regex.Pattern Class agentToolSupportClass = ec.factory.classLoader.loadClass('org.moqui.agent.AgentToolSupport')
