if (!verbLemma && (lowered.contains('status') || lowered.contains('stato') || lowered.contains('full time') || lowered.contains('ore settimanali') || lowered.contains('weekly hours'))) { verbLemma = 'set' } if (referencePronoun && lastPrimaryObject && verbLemma in ['link', 'set', 'assign', 'delete']) { targetObject = lastPrimaryObject } else if (!targetObject && referencePronoun && lastPrimaryObject) { targetObject = lastPrimaryObject } if (!verbLemma) { unsupportedFragments.add([fragment: trimmed, reason: 'unsupported_verb']) return }
Map complements = parseComplements(trimmed, verbLemma) targetObject = refineTargetObject(targetObject, complements, verbLemma) String commandId = "c${commandIndex++}" Map atomicCommand = [ commandId : commandId, sourceFragment : trimmed, verbSurface : trimmed.tokenize(' ') ? trimmed.tokenize(' ')[0] : trimmed, verbLemma : verbLemma, commandType : (verbLemma == 'read') ? 'read' : 'mutating', targetObjectText : targetObject, complements : complements, confidence : targetObject ? 0.82d : 0.55d ]
if (!targetObject && verbLemma in ['set', 'link', 'assign', 'delete'] && lastPrimaryObject) { atomicCommand.targetObjectText = lastPrimaryObject atomicCommand.targetCommandRef = lastPrimaryCommandId atomicCommand.confidence = 0.72d } if (referencePronoun && lastPrimaryObject && verbLemma in ['link', 'assign']) { atomicCommand.targetObjectText = lastPrimaryObject atomicCommand.targetCommandRef = lastPrimaryCommandId } if (verbLemma in ['link', 'set', 'assign'] && lastPrimaryCommandId) { commandGraph.add([from: lastPrimaryCommandId, to: commandId, type: 'PROVIDES_TARGET_OBJECT']) } if (verbLemma == 'create' && atomicCommand.targetObjectText) { lastPrimaryObject = atomicCommand.targetObjectText as String lastPrimaryCommandId = commandId } else if (!atomicCommand.targetObjectText) { unresolvedReferences.add([commandId: commandId, fragment: trimmed, reason: 'unknown_target_object']) }
atomicCommands.add(atomicCommand) }
workflowIntent = [ language : likelyItalian ? 'it' : 'en', mood : 'imperative', mutability : atomicCommands.any { it.commandType == 'mutating' } ? 'mutating' : 'read-only', complexity : atomicCommands.size() > 1 ? 'compound' : 'atomic' ] success = !atomicCommands.isEmpty()

