ty : t.contains('person') || t.contains('party') || t.contains('organization') || t.contains('customer') || t.contains('supplier') || t.contains('employee') || t.contains('impiegato') || t.contains('cliente') ] List<String> active = domains.findAll { it.value }.collect { it.key } boolean workflow = false if (active.size() > 1) { Set<String> activeSet = active as Set<String> Set<String> primaryDomains = activeSet.findAll { it != 'party' && !(it == 'facility' && activeSet.contains('asset')) } if (primaryDomains.size() > 1) workflow = true } return [workflow: workflow, activeDomains: active] } Closure<Boolean> isIdentityOperand = { String operandName -> String name = operandName ?: '' return name.endsWith('Id') || name.endsWith('SeqId') || name.endsWith('RelationshipId') } Closure<String> operandStem = { String operandName -> String name = operandName ?: '' if (!name) return '' name = name.replaceFirst(/RelationshipId$/, '') name = name.replaceFirst(/SeqId$/, '') name = name.replaceFirst(/Id$/, '') name = name .replaceAll(/([a-z0-9])([A-Z])/, '$1 $2') .replaceAll(/([A-Z]+)([A-Z][a-z])/, '$1 $2') .trim() return name.toLowerCase() } Closure<Integer> dependencyPreferenceScore = { Map morphismSignature -> if (!morphismSignature) return 0 String noun = (morphismSignature.noun ?: '') as String String verb = (morphismSignature.verb ?: '') as String String morphismRole = (morphismSignature.morphismRole ?: '') as String List<String> requiredNames = (morphismSignature.requiredOperandList instanceof List) ? (List<String>) morphismSignature.requiredOperandList : [] List<String> outNames = (morphismSignature.outParameterList instanceof List) ? ((List<Map>) morphismSignature.outParameterList).collect { it.name as String } : []
