int score = 0 score -= requiredIdNames.size() * 8 if (verb.toLowerCase().contains('.create')) score += 6 if (producedIdNames) score += 8 if (morphismSignature.serviceTypeEnumId) score += 10 if (morphismRole == 'composite_morphism') score += 8 if (morphismRole == 'entity_auto_service') score -= 2 if (noun ==~ /.*(Item|Detail|Assoc|Appl|SubPeriod|SubPeriods)$/) score -= 12 if (noun ==~ /.*(Budget|Order|Project|Employment|Person|Organization|Asset)$/) score += 8 return score } Closure<Integer> domainAlignmentScore = { Map morphismSignature, String text -> Set<String> queryTokens = tokenizePlanner(text) Set<String> strongDomains = [ 'budget', 'order', 'project', 'asset', 'facility', 'warehouse', 'invoice', 'payment', 'employment', 'employee', 'position', 'shipment', 'request' ] as Set<String> Set<String> domainTokens = queryTokens.intersect([ 'budget', 'order', 'project', 'asset', 'facility', 'warehouse', 'invoice', 'payment', 'employment', 'employee', 'position', 'party', 'person', 'organization', 'shipment', 'request', 'product' ] as Set<String>) if (!domainTokens) return 0 String structuralHaystack = [ morphismSignature.serviceName, morphismSignature.noun, morphismSignature.actionNoun, morphismSignature.domainObject, morphismSignature.actionObject, morphismSignature.objectName ].findAll { it }.join(' ').toLowerCase() String descriptiveHaystack = normalize(morphismSignature.description).toLowerCase() int score = 0 int matchCount = domainTokens.count { String term -> structuralHaystack.contains(term) || descriptiveHaystack.contains(term) } int missingCount = domainTokens.size() - matchCount if (matchCount > 0) score += matchCount * 8 if (missingCount > 0) score -= missingCount * 10 Set<String> activeStrongDomains = queryTokens.intersect(strongDomains) Set<String> foreignStrongDomains = strongDomains - activeStrongDomains foreignStrongDomains.each { String foreignDomain -> if (structuralHaystack.contains(foreignDomain)) score -= 12 } return score } Closure<Map> enrichCandidate Closure<String> lookupKeyForOperand = { String operandName -> switch (operandName ?: '') { case ['organizationPartyId', 'employingOrganizationPartyId', 'ownerPartyId', 'customerPartyId', 'supplierPartyId', 'fromPartyId', 'toPartyId', 'partyId']: return 'party' case 'customerPartyId': case 'vendorPartyId': case 'organizationPartyId': case 'employingOrganizationPartyId': case 'ownerPartyId': case 'supplierPartyId': case 'partyId': return 'party' case 'budgetTypeEnumId': return 'budgetType' case 'timePeriodId': return 'fiscalYearTimePeriod' case 'glAccountId': return 'glAccount' case 'facilityId': return 'facility' case 'assetId': return 'asset' case 'productId': return 'product' case 'requestId': return 'request' case 'orderId': case 'orderPartSeqId': return 'salesOrderPart' case 'orderItemSeqId': return 'salesOrderItem' case 'rootWorkEffortId': return 'project' case 'emplPositionClassId': return 'emplPositionClass' case 'emplPositionId': return 'emplPosition' case 'statusId': return 'status' case 'productStoreId': return 'productStore' case 'currencyUomId': return 'currencyUom' default: return null } } Closure<String> extractLookupTextForOperand = { String operandName, String text -> if (!operandName || !text) return null if (operandName == 'budgetTypeEnumId' || operandName == 'timePeriodId') return text
