import org.moqui.impl.context.ArtifactExecutionFacadeImpl
import org.moqui.impl.service.ServiceDefinition

success = false
operation = 'algebraic_morphism_chain'
stepResults = []

Map currentParameters = [:]
if (parameters instanceof Map) {
    (parameters as Map).each { Object k, Object v ->
        if (k != null && k.toString() != 'null' && !k.toString().trim().isEmpty()) {
            currentParameters[k.toString()] = v
        }
    }
}
resolvedParameters = new LinkedHashMap(currentParameters)
finalResult = [:]
errors = []

Set<String> entityAutoVerbs = ['create', 'update', 'store', 'delete'] as Set<String>
Closure<String> serviceVerb = { String currentServiceName ->
    return ServiceDefinition.getVerbFromName(currentServiceName ?: '') ?: ''
}
Closure<String> serviceNoun = { String currentServiceName ->
    return ServiceDefinition.getNounFromName(currentServiceName ?: '') ?: ''
}
Closure<String> authzActionEnumIdForService = { String currentServiceName ->
    String verb = serviceVerb(currentServiceName)
    return ServiceDefinition.getVerbAuthzActionEnum(verb)?.name()
}
Closure<Boolean> registeredMorphism = { String currentServiceName ->
    if (!currentServiceName) return false
    return ec.entity.find('moqui.math.ct.Morphism')
            .condition('categoryId', 'AgentXmlActionsDsl')
            .condition('serviceName', currentServiceName)
            .useCache(true)
            .one() != null
}
Closure<Boolean> entityAutoService = { String currentServiceName ->
    String verb = serviceVerb(currentServiceName)
    String noun = serviceNoun(currentServiceName)
    return entityAutoVerbs.contains(verb) && noun && ec.entity.isEntityDefined(noun)
}
Closure<String> lookupKeyForOperand = { String operandName ->
    switch (operandName ?: '') {
        case ['organizationPartyId', 'employingOrganizationPartyId', 'ownerPartyId', 'customerPartyId', 'supplierPartyId', 'fromPartyId', 'toPartyId', 'partyId']:
            return 'party'
        case 'budgetTypeEnumId': return 'budgetType'
        case 'timePeriodId': return 'fiscalYearTimePeriod'
        case 'glAccountId': return 'glAccount'
        case 'facilityId': return 'facility'
        case 'assetId': return 'asset'
        case 'productId': return 'product'
        case 'requestId': return 'request'
        case 'orderId':
        case 'orderPartSeqId': return 'salesOrderPart'
        case 'orderItemSeqId': return 'salesOrderItem'
        case 'rootWorkEffortId': return 'project'
        case 'emplPositionClassId': return 'emplPositionClass'
        case 'emplPositionId': return 'emplPosition'
        case 'statusId': return 'status'
        case 'productStoreId': return 'productStore'
        case 'currencyUomId': return 'currencyUom'
        default: return null
    }
}
Closure<Boolean> resolveLookupOperandValue = { Map effectiveParameters, String operandName ->
    if (!operandName || effectiveParameters[operandName] != null) return false
    String lookupKey = lookupKeyForOperand(operandName)
    if (!lookupKey) return false
    String lookupField = "__lookup__${operandName}".toString()
    String lookupTextField = "${operandName}LookupText".toString()
    String lookupText = (effectiveParameters.remove(lookupField) ?: effectiveParameters.remove(lookupTextField)) as String
    if (!lookupText) return false
    String organizationPartyId = (effectiveParameters.organizationPartyId ?: effectiveParameters.employingOrganizationPartyId ?: effectiveParameters.ownerPartyId ?: resolvedParameters.organizationPartyId ?: '') as String
    String roleTypeId = null
    if (operandName == 'customerPartyId' || operandName == 'toPartyId') roleTypeId = 'Customer'
    else if (operandName == 'supplierPartyId') roleTypeId = 'Supplier'
    Map lookupResult = ec.service.sync().name('org.moqui.agent.AgentExecutionServices.find#LookupRecord')
            .parameters([
                    lookupKey: lookupKey,
                    lookupText: lookupText,
                    organizationPartyId: organizationPartyId,
                    roleTypeId: roleTypeId
            ]).call()
    if (ec.message.hasError()) {
        ec.message.clearErrors()
        return false
    }
    if (lookupResult?.uniqueMatch && lookupResult?.recordId) {
        effectiveParameters[operandName] = lookupResult.recordId
        return true
    }
    List<Map> unresolvedLookups = (effectiveParameters.__unresolvedLookups instanceof List) ? (List<Map>) effectiveParameters.__unresolvedLookups : []
    unresolvedLookups.add([
            operandName: operandName,
            lookupKey  : lookupKey,
            lookupText : lookupText
    ])
    effectiveParameters.__unresolvedLookups = unresolvedLookups
    return false
}
Closure<Object> normalizeTypedParameterValue = { Map param, Object rawValue ->
    if (rawValue == null) return null
    String typeName = ((param?.type ?: '') as String).toLowerCase()
    String textValue = rawValue.toString().trim()
    if (!textValue) return rawValue
    boolean isIntegerType = typeName in ['integer', 'long'] ||
            typeName.endsWith('.integer') || typeName.endsWith('.long')
    boolean isDecimalType = typeName in ['float', 'double', 'bigdecimal', 'number', 'currency-amount'] ||
            typeName.endsWith('.float') || typeName.endsWith('.double') ||
            typeName.endsWith('.bigdecimal') || typeName.endsWith('.biginteger')
    boolean isDateType = typeName == 'date' || typeName.endsWith('.date')
    boolean isTimestampType = typeName in ['date-time', 'timestamp'] ||
            typeName.endsWith('.timestamp') || typeName.contains('date-time')
    boolean isBooleanType = typeName == 'boolean' || typeName.endsWith('.boolean')
    if (isIntegerType) {
        String normalized = textValue.replace(',', '.')
        if (normalized ==~ /-?\d+(?:\.0+)?/) return normalized.contains('.') ? Long.valueOf(normalized.substring(0, normalized.indexOf('.'))) : Long.valueOf(normalized)
    }
    if (isDecimalType) {
        String normalized = textValue.replace(',', '.')
        if (normalized ==~ /-?\d+(?:\.\d+)?/) return new BigDecimal(normalized)
    }
    if (isDateType || isTimestampType) {
        if (textValue ==~ /\d{1,2}\/\d{1,2}\/\d{2,4}/) {
            List<String> parts = textValue.split('/') as List<String>
            if (parts.size() == 3) {
                int day = Integer.parseInt(parts[0])
                int month = Integer.parseInt(parts[1])
                int year = Integer.parseInt(parts[2])
                if (year < 100) year += 2000
                String isoDate = String.format('%04d-%02d-%02d', year, month, day)
                if (isDateType && !isTimestampType) return java.sql.Date.valueOf(isoDate)
                return java.sql.Timestamp.valueOf("${isoDate} 00:00:00")
            }
        }
        if (isDateType && !isTimestampType && (textValue ==~ /\d{4}-\d{2}-\d{2}/)) return java.sql.Date.valueOf(textValue)
        if (textValue ==~ /\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/) return java.sql.Timestamp.valueOf(textValue)
        String loweredDateTimeValue = textValue.toLowerCase()
        if (loweredDateTimeValue ==~ /\d{4}-\d{2}-\d{2}t\d{2}:\d{2}:\d{2}/) return java.sql.Timestamp.valueOf(loweredDateTimeValue.replace('t', ' '))
    }
    if (isBooleanType) {
        if (textValue.equalsIgnoreCase('true') || textValue.equalsIgnoreCase('y') || textValue == '1') return true
        if (textValue.equalsIgnoreCase('false') || textValue.equalsIgnoreCase('n') || textValue == '0') return false
    }
    return rawValue
}
Closure<List<String>> validateSemanticAssertions = { Map planStep, List<Map> inParameterList, List<Map> preparedBatches ->
    List<String> issues = []
    List<Map> assertions = (planStep?.semanticAssertions instanceof List) ? (List<Map>) planStep.semanticAssertions : []
    preparedBatches.each { Map batch ->
        List<Map> unresolvedLookups = (batch.__unresolvedLookups instanceof List) ? (List<Map>) batch.__unresolvedLookups : []
        unresolvedLookups.each { Map unresolved ->
            String operandName = (unresolved.operandName ?: '') as String
            String lookupKey = (unresolved.lookupKey ?: '') as String
            String lookupText = (unresolved.lookupText ?: '') as String
            if (operandName && lookupKey && lookupText) {
                issues.add("Semantic lookup binding unresolved for ${operandName} on ${(planStep?.serviceName ?: '')}: ${lookupKey} '${lookupText}'")
            }
        }
    }
    assertions.each { Map assertion ->
        String type = (assertion.type ?: '') as String
        List<String> paramNames = (assertion.paramNames instanceof List) ? (List<String>) assertion.paramNames : []
        if (type == 'batch_count') {
            int expected = (assertion.expectedCount ?: 0) as Integer
            if (expected > 0 && preparedBatches.size() != expected) {
                issues.add("Semantic batch count mismatch for ${(planStep?.serviceName ?: '')}: expected ${expected}, found ${preparedBatches.size()}")
            }
        } else if (type == 'batch_binding') {
            boolean present = preparedBatches && preparedBatches.every { Map batch ->
                paramNames.any { String pName ->
                    String lookupField = "__lookup__${pName}".toString()
                    (batch.containsKey(pName) && batch[pName] != null && batch[pName].toString()) ||
                            (batch.containsKey(lookupField) && batch[lookupField] != null && batch[lookupField].toString())
                }
            }
            if (!present) {
                issues.add("Semantic batch binding missing for ${(assertion.semantic ?: 'batch')} on ${(planStep?.serviceName ?: '')}")
            }
        } else if (type == 'root_binding') {
            Map firstBatch = preparedBatches ? preparedBatches[0] : [:]
            boolean present = paramNames.any { String pName ->
                String lookupField = "__lookup__${pName}".toString()
                (firstBatch.containsKey(pName) && firstBatch[pName] != null && firstBatch[pName].toString()) ||
                        (firstBatch.containsKey(lookupField) && firstBatch[lookupField] != null && firstBatch[lookupField].toString())
            }
            if (!present) {
                issues.add("Semantic root binding missing for ${(assertion.semantic ?: 'root')} on ${(planStep?.serviceName ?: '')}")
            }
        } else if (type == 'minimum_effect_binding') {
            Map firstBatch = preparedBatches ? preparedBatches[0] : [:]
            int minCount = (assertion.minBoundNonIdentityParams ?: 1) as Integer
            Set<String> identityOperandNames = inParameterList.findAll { Map param ->
                Boolean.TRUE.equals(param?.required) && Boolean.TRUE.equals(param?.identity)
            }.collect { Map param -> (param?.name ?: '') as String }.findAll { it } as Set<String>
            int actualCount = firstBatch.keySet().count { String bindingName ->
                String normalizedBindingName = (bindingName ?: '').startsWith('__lookup__') ?
                        (bindingName ?: '').substring('__lookup__'.length()) : (bindingName ?: '')
                normalizedBindingName && !identityOperandNames.contains(normalizedBindingName)
            }
            if (actualCount < minCount) {
                issues.add("Semantic mutation binding too weak for ${(planStep?.serviceName ?: '')}")
            }
        } else if (type == 'unsupported_binding') {
            issues.add("Semantic binding unsupported for ${(assertion.semantic ?: 'binding')} on ${(planStep?.serviceName ?: '')}")
        }
    }
    preparedBatches.each { Map batch ->
        if (batch.containsKey('quantityCancelled') || batch.containsKey('promoQuantity')) {
            issues.add("Suspicious quantity binding detected for ${(planStep?.serviceName ?: '')}")
        }
    }
    return issues
}

List<Map> planSteps = (executionPlanGraph instanceof List && executionPlanGraph) ? (List<Map>) executionPlanGraph : []
if (!planSteps && selectedService) {
    planSteps = [[step: 1, serviceName: selectedService, relation: 'primary']]
}
if (!planSteps) {
    errors = ['No morphism steps were provided for execution.']
    return
}

this.executionPlanGraph = planSteps
this.selectedService = selectedService

if (Boolean.TRUE.equals(dryRun)) {
    success = true
    this.dryRun = true
    message = 'Dry run only: algebraic execution plan compiled but not executed.'
    return
}

Map<String, Map> signatureByServiceName = [:]
Map previewParameters = new LinkedHashMap(currentParameters)
for (Map planStep in planSteps) {
    String stepServiceName = (planStep?.serviceName ?: '') as String
    if (!stepServiceName) continue

    if (!ec.service.isServiceDefined(stepServiceName) && !entityAutoService(stepServiceName)) {
        errors = ["Service not defined for morphism step ${stepServiceName}."]
        return
    }
    if (!registeredMorphism(stepServiceName) && !entityAutoService(stepServiceName)) {
        errors = ["Service ${stepServiceName} is not registered in the morphism catalog."]
        return
    }

    Map signatureResult = ec.service.sync()
            .name('org.moqui.agent.AgentAlgebraicServices.get#MorphismSignature')
            .parameters([serviceName: stepServiceName]).call()
    if (ec.message.hasError()) {
        errors = [ec.message.errorsString]
        ec.message.clearErrors()
        return
    }
    Map signature = (signatureResult?.morphism instanceof Map) ? (Map) signatureResult.morphism : [:]
    signatureByServiceName[stepServiceName] = signature
    List<Map> inParameterList = (signature.inParameterList instanceof List) ? (List<Map>) signature.inParameterList : []

    List<String> missingOperands = []
    Map stepBindings = (planStep?.stepBindings instanceof Map) ? new LinkedHashMap(planStep.stepBindings as Map) : [:]
    List<Map> parameterBatchList = (planStep?.parameterBatchList instanceof List) ? (List<Map>) planStep.parameterBatchList : []
    Map stepParameters = [:]
    inParameterList.each { Map param ->
        String paramName = (param?.name ?: '') as String
        boolean required = Boolean.TRUE.equals(param?.required)
        String lookupField = paramName ? "__lookup__${paramName}".toString() : null
        if (paramName && stepBindings.containsKey(paramName)) {
            stepParameters[paramName] = stepBindings[paramName]
        } else if (paramName && previewParameters.containsKey(paramName)) {
            stepParameters[paramName] = previewParameters[paramName]
        } else if (lookupField && stepBindings.containsKey(lookupField)) {
            stepParameters[lookupField] = stepBindings[lookupField]
        } else if (lookupField && previewParameters.containsKey(lookupField)) {
            stepParameters[lookupField] = previewParameters[lookupField]
        } else if (paramName && required) {
            missingOperands.add(paramName)
        }
    }
    if (missingOperands) {
        errors = ["Missing required operands for ${stepServiceName}: ${missingOperands.join(', ')}"]
        return
    }

    List<Map> previewBatches = parameterBatchList ? parameterBatchList : [[:]]
    List<Map> preparedPreviewBatches = []
    previewBatches.each { Map rawBatch ->
        Map prepared = new LinkedHashMap(stepParameters)
        if (rawBatch instanceof Map) prepared.putAll(rawBatch as Map)
        inParameterList.each { Map param ->
            String pName = (param?.name ?: '') as String
            if (pName) {
                resolveLookupOperandValue(prepared, pName)
                if (prepared.containsKey(pName)) prepared[pName] = normalizeTypedParameterValue(param, prepared[pName])
            }
        }
        preparedPreviewBatches.add(prepared)
    }
    List<String> semanticIssues = validateSemanticAssertions(planStep, inParameterList, preparedPreviewBatches)
    if (semanticIssues) {
        errors = semanticIssues
        return
    }

    List<String> producedOperandNames = []
    if (signature.producedOperandList instanceof List) {
        producedOperandNames.addAll(((List) signature.producedOperandList).collect { it?.toString() }.findAll { it })
    }
    if (signature.producedIdOperandList instanceof List) {
        producedOperandNames.addAll(((List) signature.producedIdOperandList).collect { it?.toString() }.findAll { it })
    }
    if (planStep?.producesOperands instanceof List) {
        producedOperandNames.addAll(((List) planStep.producesOperands).collect { it?.toString() }.findAll { it })
    }
    producedOperandNames.unique().each { String producedName ->
        if (producedName && !previewParameters.containsKey(producedName)) {
            previewParameters[producedName] = "__planned__${planStep.step ?: 0}__${producedName}"
        }
    }
}

for (Map planStep in planSteps) {
    String stepServiceName = (planStep?.serviceName ?: '') as String
    if (!stepServiceName) continue

    if (!ec.service.isServiceDefined(stepServiceName) && !entityAutoService(stepServiceName)) {
        errors = ["Service not defined for morphism step ${stepServiceName}."]
        return
    }
    if (!registeredMorphism(stepServiceName) && !entityAutoService(stepServiceName)) {
        errors = ["Service ${stepServiceName} is not registered in the morphism catalog."]
        return
    }

    Map signature = signatureByServiceName[stepServiceName]
    if (!(signature instanceof Map) || signature.isEmpty()) {
        Map signatureResult = ec.service.sync()
                .name('org.moqui.agent.AgentAlgebraicServices.get#MorphismSignature')
                .parameters([serviceName: stepServiceName]).call()
        if (ec.message.hasError()) {
            errors = [ec.message.errorsString]
            ec.message.clearErrors()
            return
        }
        signature = (signatureResult?.morphism instanceof Map) ? (Map) signatureResult.morphism : [:]
    }
    List<Map> inParameterList = (signature.inParameterList instanceof List) ? (List<Map>) signature.inParameterList : []
    List<String> missingOperands = []
    Map stepBindings = (planStep?.stepBindings instanceof Map) ? new LinkedHashMap(planStep.stepBindings as Map) : [:]
    List<Map> parameterBatchList = (planStep?.parameterBatchList instanceof List) ? (List<Map>) planStep.parameterBatchList : []
    Map stepParameters = [:]
    inParameterList.each { Map param ->
        String paramName = (param?.name ?: '') as String
        boolean required = Boolean.TRUE.equals(param?.required)
        String lookupField = paramName ? "__lookup__${paramName}".toString() : null
        if (paramName && stepBindings.containsKey(paramName)) {
            stepParameters[paramName] = stepBindings[paramName]
        } else if (paramName && currentParameters.containsKey(paramName)) {
            stepParameters[paramName] = currentParameters[paramName]
        } else if (lookupField && stepBindings.containsKey(lookupField)) {
            stepParameters[lookupField] = stepBindings[lookupField]
        } else if (lookupField && currentParameters.containsKey(lookupField)) {
            stepParameters[lookupField] = currentParameters[lookupField]
        } else if (paramName && required) {
            missingOperands.add(paramName)
        }
    }
    if (missingOperands) {
        stepResults << [
                step : planStep.step,
                relation : planStep.relation,
                serviceName : stepServiceName,
                parameters : stepParameters,
                result : [
                        success : false,
                        serviceName : stepServiceName,
                        errorMessage : "Missing required operands for ${stepServiceName}: ${missingOperands.join(', ')}",
                        errors : ["Missing required operands for ${stepServiceName}: ${missingOperands.join(', ')}"]
                ]
        ]
        errors = ["Missing required operands for ${stepServiceName}: ${missingOperands.join(', ')}"]
        return
    }

    String authzActionEnumId = authzActionEnumIdForService(stepServiceName)
    if (!Boolean.TRUE.equals(internalDisableAuthzForSmokeTest)) {
        boolean authorized = authzActionEnumId ?
                ArtifactExecutionFacadeImpl.isPermitted("AT_SERVICE:${authzActionEnumId}:${stepServiceName}", ec) : false
        if (!authorized) {
            stepResults << [
                    step : planStep.step,
                    relation : planStep.relation,
                    serviceName : stepServiceName,
                    parameters : stepParameters,
                    result : [
                            success : false,
                            serviceName : stepServiceName,
                            authzActionEnumId : authzActionEnumId,
                            errorMessage : "Access denied for service ${stepServiceName}",
                            errors : ["Access denied for service ${stepServiceName}"]
                    ]
            ]
            errors = ["Access denied for service ${stepServiceName}"]
            return
        }
    }

    List<Map> executionBatches = parameterBatchList ? parameterBatchList : [[:]]
    List<Map> preparedBatches = []
    executionBatches.each { Map rawBatch ->
        Map prepared = new LinkedHashMap(stepParameters)
        if (rawBatch instanceof Map) prepared.putAll(rawBatch as Map)
        inParameterList.each { Map param ->
            String pName = (param?.name ?: '') as String
            if (pName) {
                resolveLookupOperandValue(prepared, pName)
                if (prepared.containsKey(pName)) prepared[pName] = normalizeTypedParameterValue(param, prepared[pName])
            }
        }
        preparedBatches.add(prepared)
    }
    List<String> semanticIssues = validateSemanticAssertions(planStep, inParameterList, preparedBatches)
    if (semanticIssues) {
        stepResults << [
                step : planStep.step,
                relation : planStep.relation,
                serviceName : stepServiceName,
                parameters : stepParameters,
                result : [
                        success : false,
                        serviceName : stepServiceName,
                        errorMessage : semanticIssues.join('; '),
                        errors : semanticIssues
                ]
        ]
        errors = semanticIssues
        return
    }
    List<Map> batchResults = []
    Map serviceResult = [:]
    for (Map preparedBindings in preparedBatches) {
        Map effectiveParameters = new LinkedHashMap(preparedBindings ?: [:])
        Map sanitizedParameters = [:]
        effectiveParameters.each { Object k, Object v ->
            if (k != null && k.toString() != 'null' && !k.toString().trim().isEmpty() && !k.toString().startsWith('__lookup__')) {
                sanitizedParameters[k.toString()] = v
            }
        }
        try {
            List stackFrames = (ec.context.getStack() as List)
            stackFrames?.each { Object frame ->
                if (frame instanceof Map) {
                    try { ((Map) frame).remove(null); ((Map) frame).remove('null') } catch (Throwable ignored) {}
                }
            }
        } catch (Throwable ignored) {}
        Map oneResult = [:]
        try {
            def call = ec.service.sync()
                    .name(stepServiceName)
                    .requireNewTransaction(true)
                    .parameters(sanitizedParameters)
            if (Boolean.TRUE.equals(internalDisableAuthzForSmokeTest)) call = call.disableAuthz()
            oneResult = (call.call() as Map) ?: [:]
        } catch (Throwable serviceFailure) {
            String failureMessage = serviceFailure.message ?: serviceFailure.toString()
            ec.message.clearErrors()
            oneResult = [
                    success : false,
                    serviceName : stepServiceName,
                    errorType : serviceFailure.getClass().getName(),
                    errorMessage : failureMessage,
                    errors : [failureMessage]
            ]
        }
        if (ec.message.hasError()) {
            String errorsAfterCall = ec.message.errorsString
            ec.message.clearErrors()
            oneResult = (oneResult instanceof Map) ? new LinkedHashMap(oneResult as Map) : [:]
            oneResult.success = false
            oneResult.serviceName = stepServiceName
            oneResult.errorMessage = "Service ${stepServiceName} returned errors: ${errorsAfterCall}"
            oneResult.errors = errorsAfterCall ? errorsAfterCall.split(/;\s*/) as List : []
        } else if (oneResult instanceof Map && !oneResult.containsKey('success')) {
            oneResult = new LinkedHashMap(oneResult as Map)
            oneResult.success = true
        }
        batchResults.add([
                parameters: effectiveParameters,
                result    : oneResult
        ])
        serviceResult = oneResult ?: [:]
        if (!Boolean.TRUE.equals(oneResult?.success)) break
        if (oneResult instanceof Map) {
            oneResult.each { Object key, Object value ->
                if (key != null && value != null && !(value instanceof Map) && !(value instanceof List)) {
                    currentParameters[key.toString()] = value
                }
            }
        }
    }

    stepResults << [
            step : planStep.step,
            relation : planStep.relation,
            serviceName : stepServiceName,
            parameters : stepParameters,
            result : serviceResult,
            batchResults : batchResults,
            authzActionEnumId : authzActionEnumId
    ]
    if (!Boolean.TRUE.equals(serviceResult?.success)) {
        errors = (serviceResult?.errors instanceof List) ? (List) serviceResult.errors :
                [serviceResult?.errorMessage ?: "Execution failed for ${stepServiceName}"]
        return
    }
}

success = true
resolvedParameters = currentParameters
finalResult = stepResults ? (stepResults[-1].result as Map) : [:]

import java.util.Locale import java.util.regex.Matcher import java.util.regex.Pattern import org.moqui.impl.actions.XmlAction import org.moqui.impl.context.ExecutionContextFactoryImpl import org.moqui.impl.context.ExecutionContextImpl
Closure<String> escapeXml = { Object value -> String text = value == null ? '' : value.toString() text = text.replace('&', '&amp;') text = text.replace('<', '&lt;') text = text.replace('>', '&gt;') text = text.replace('"', '&quot;') return text } Closure<String> sq = { Object value -> String text = value == null ? '' : value.toString() text = text.replace("\\", "\\\\").replace("'", "\\'") return "'${text}'" }
errors = [] success = false milestoneIds = [] taskIds = [] projectPlan = [:]
String prompt = (queryText ?: '').trim() if (!prompt) { errors.add('queryText is required') return }
String flattened = prompt.replaceAll(/[\r\n]+/, ' ').replaceAll(/\s+/, ' ').trim()
Matcher projectMatcher = Pattern.compile( /(?i)\b(?:nuovo\s+progetto|progetto|commessa)\s+(.+?),\s*con\s+priorit[aà]\s+(\d+)/ ).matcher(flattened) if (!projectMatcher.find()) { errors.add('Unable to parse project root from prompt.') return } String projectName = (projectMatcher.group(1) ?: '').trim() Long priorityValue = ((projectMatcher.group(2) ?: '5') as String).toLong()
String purposeEnumId = 'WepPrProdDev' Matcher purposeMatcher = Pattern.compile(/(?i)\bpurpose\s+([^,.;]+?)(?=(?:,|\.|$))/).matcher(flattened) if (purposeMatcher.find()) { String purposeText = (purposeMatcher.group(1) ?: '').trim() if (!purposeText.equalsIgnoreCase('Product Development')) { errors.add("Unsupported purpose text for prototype: ${purposeText}") return } }
Matcher milestoneMatcher = Pattern.compile(/(?i)\bmilestone\s+([^,.;]+?)\s+e\s+([^,.;]+?)\.(?:\s|$)/).matcher(flattened) if (!milestoneMatcher.find()) { errors.add('Unable to parse the two milestone names from prompt.') return } String milestoneOneName = (milestoneMatcher.group(1) ?: '').trim() String milestoneTwoName = (milestoneMatcher.group(2) ?: '').trim()
Matcher firstTasksMatcher = Pattern.compile( /(?i)\bsotto\s+al\s+primo\s+milestone\s+\d+\s+tasks?\s+con\s+nome\s+(.+?)\s+,\s*e\s+sotto\s+al\s+secondo\s+milestone/ ).matcher(flattened) if (!firstTasksMatcher.find()) { errors.add('Unable to parse tasks under the first milestone.') return } String firstTasksText = (firstTasksMatcher.group(1) ?: '').trim() List<String> milestoneOneTasks = firstTasksText.split(/\s+ed\s+/) .collect { (it ?: '').trim().replaceAll(/\s+$/, '') } .findAll { it } as List<String>
Matcher secondTasksMatcher = Pattern.compile( /(?i)\bsotto\s+al\s+secondo\s+milestone\s+i?\s*\d+\s+tasks?\s+(.+?)\.\s*Tutti\s+con\s+priorit[aà]/ ).matcher(flattened) if (!secondTasksMatcher.find()) { errors.add('Unable to parse tasks under the second milestone.') return } String secondTasksText = (secondTasksMatcher.group(1) ?: '').trim() List<String> milestoneTwoTasks = secondTasksText.split(/\s*,\s*/) .collect { (it ?: '').trim().replaceAll(/^\s*e\s+/, '') } .findAll { it } as List<String> if (milestoneTwoTasks.size() == 2) { String firstCombined = milestoneTwoTasks[0] Matcher nestedTaskMatcher = Pattern.compile(/(?i)^(.+?)\s+e\s+(Installazione\s+software)\s*$/).matcher(firstCombined) if (nestedTaskMatcher.find()) { milestoneTwoTasks = [ (nestedTaskMatcher.group(1) ?: '').trim(), (nestedTaskMatcher.group(2) ?: '').trim(), milestoneTwoTasks[1] ].findAll { it } as List<String> } }
Matcher assigneeMatcher = Pattern.compile( /(?i)\bassegna\s+tutti\s+i\s+ta(?:ks|ks)\s+a\s+(.+?)\s+con\s+ruolo\s+([^,.;]+?)(?=(?:,|\.|$))/ ).matcher(flattened) if (!assigneeMatcher.find()) { errors.add('Unable to parse assignee and role from prompt.') return } String assigneeName = (assigneeMatcher.group(1) ?: '').trim() String assigneeRoleText = (assigneeMatcher.group(2) ?: '').trim() String assignRoleTypeId = assigneeRoleText.equalsIgnoreCase('Project Manager') ? 'ProjectManager' : 'Manager'
if (milestoneOneTasks.size() != 2 || milestoneTwoTasks.size() != 3) { errors.add("Prototype expects exactly 2 tasks under milestone one and 3 tasks under milestone two; got ${milestoneOneTasks.size()} and ${milestoneTwoTasks.size()}.") return }
projectPlan = [ projectName : projectName, priority : priorityValue, purposeEnumId : purposeEnumId, assigneeName : assigneeName, assignRoleTypeId : assignRoleTypeId, milestones : [ [name: milestoneOneName, tasks: milestoneOneTasks], [name: milestoneTwoName, tasks: milestoneTwoTasks] ] ]
List<String> xmlLines = [] xmlLines << '<actions>' xmlLines << ' <service-call name="org.moqui.agent.AgentExecutionServices.find#LookupRecord" out-map="assigneeLookup"' xmlLines << " in-map=\"[lookupKey:'party', lookupText:${sq(assigneeName)}]\"/>" xmlLines << ' <if condition="!(assigneeLookup?.uniqueMatch &amp;&amp; assigneeLookup?.recordId)">' xmlLines << " <return error=\"true\" message=\"Assignee ${escapeXml(assigneeName)} was not found.\"/>" xmlLines << ' </if>' xmlLines << ' <set field="assigneePartyId" from="assigneeLookup.recordId"/>' xmlLines << ' <service-call name="mantle.work.ProjectServices.create#Project" out-map="projectOut"' xmlLines << " in-map=\"[workEffortName:${sq(projectName)}, priority:${priorityValue}, purposeEnumId:${sq(purposeEnumId)}, assignToPartyId:assigneePartyId, assignRoleTypeId:${sq(assignRoleTypeId)}]\"/>" xmlLines << ' <set field="projectId" from="projectOut.workEffortId"/>' xmlLines << " <set field=\"milestoneOneId\" from=\"projectId + '-MS1'\"/>" xmlLines << " <set field=\"milestoneTwoId\" from=\"projectId + '-MS2'\"/>" xmlLines << ' <service-call name="mantle.work.ProjectServices.create#Milestone"' xmlLines << " in-map=\"[rootWorkEffortId:projectId, workEffortId:milestoneOneId, workEffortName:${sq(milestoneOneName)}, statusId:'WeInPlanning']\"/>" xmlLines << ' <service-call name="mantle.work.ProjectServices.create#Milestone"' xmlLines << " in-map=\"[rootWorkEffortId:projectId, workEffortId:milestoneTwoId, workEffortName:${sq(milestoneTwoName)}, statusId:'WeInPlanning']\"/>"
int taskCounter = 1 milestoneOneTasks.each { String taskName -> xmlLines << " <service-call name=\"mantle.work.TaskServices.create#Task\" out-map=\"taskOut${taskCounter}\"" xmlLines << " in-map=\"[rootWorkEffortId:projectId, milestoneWorkEffortId:milestoneOneId, workEffortName:${sq(taskName)}, priority:${priorityValue}, assignToPartyId:assigneePartyId, assignRoleTypeId:${sq(assignRoleTypeId)}]\"/>" taskCounter++ } milestoneTwoTasks.each { String taskName -> xmlLines << " <service-call name=\"mantle.work.TaskServices.create#Task\" out-map=\"taskOut${taskCounter}\"" xmlLines << " in-map=\"[rootWorkEffortId:projectId, milestoneWorkEffortId:milestoneTwoId, workEffortName:${sq(taskName)}, priority:${priorityValue}, assignToPartyId:assigneePartyId, assignRoleTypeId:${sq(assignRoleTypeId)}]\"/>" taskCounter++ } List<String> taskRefs = (1..(taskCounter - 1)).collect { "taskOut${it}.workEffortId" } xmlLines << ' <set field="milestoneIds" from="[milestoneOneId, milestoneTwoId]"/>' xmlLines << " <set field=\"taskIds\" from=\"[${taskRefs.join(', ')}]\"/>" xmlLines << ' <set field="result" from="[projectId:projectId, milestoneIds:milestoneIds, taskIds:taskIds]"/>' xmlLines << '</actions>'
generatedXmlActions = xmlLines.join('\n')
Map traceResult = ec.service.sync() .name('org.moqui.agent.AgentAlgebraicServices.record#GeneratedXmlActionMorphism') .parameters([ prototypeKey : 'project-aggregate', serviceVerb : 'execute', serviceNoun : "ProjectAggregate${projectName.replaceAll(/[^A-Za-z0-9]+/, '')}", serviceDescription : "Runtime-generated xml-actions service for project aggregate prompt '${projectName}'. It creates a project root, two milestones, and ordered tasks inside the same Moqui execution context.", generatedXmlActions : generatedXmlActions, sourceObjectId : 'AgentXmlCtxObj', targetObjectId : 'AgentXmlCtxObj', requiredOperandsJson : '["queryText"]', producedOperandsJson : '["projectId","milestoneIds","taskIds"]', selectionDescription : 'Select when the user asks to create a project root with milestones and tasks as a single rooted aggregate.', bindingDescription : 'Bindings are resolved inside the generated xml-actions: assignee lookup first, then project creation, milestone creation, and task creation with propagated identifiers.' ]).call() ?: [:] if (!Boolean.TRUE.equals(traceResult.success)) { errors.add('Unable to record generated project aggregate morphism.') return } generatedServiceLocation = traceResult.generatedServiceLocation as String generatedServiceFilePath = traceResult.generatedServiceFilePath as String generatedServiceName = traceResult.generatedServiceName as String generatedMorphismId = traceResult.morphismId as String
XmlAction xmlAction = new XmlAction((ExecutionContextFactoryImpl) ec.factory, generatedXmlActions, 'agent://project-aggregate-xml-actions-prototype') generatedGroovy = xmlAction.getGroovyString() if (Boolean.TRUE.equals(dryRun)) { success = true return }
xmlAction.run((ExecutionContextImpl) ec) if (ec.message.hasError()) { errors.addAll((ec.message.errors ?: []) as List) ec.message.clearErrors() return }
